  const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let state=C.initialState(), documents=[], step=0, visited=new Set([0]), page='home', isDemo=false, dirty=false, persist=false, toastTimer, showAll=false, busy=false;
  let saved=load(DRAFT_KEY,null);
  function load(key,fallback){try{const value=localStorage.getItem(key);return value&&value.length<1500000?JSON.parse(value):fallback;}catch{return fallback;}}
  function store(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{return false;}}
  function record(name,unique=false){window.SRMetrics?.record(name,unique,isDemo);}
  function today(){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Amsterdam',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
  function result(){return C.evaluate(state,documents,{today:today()});}
  function toast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),4200);}
  function saveIfEnabled(){if(persist){saved={version:1,state:C.sanitizeState(state),demo:isDemo,updatedAt:new Date().toISOString()};if(!store(DRAFT_KEY,saved)){persist=false;toast('Opslaan is niet beschikbaar. Download je projectbestand om je gegevens te bewaren.');}}}
  function invalidateConfirmations(key){
    if(['brand','model','meldcode','productRoute'].includes(key)) state.codeConfirmed=false;
    if(['applicantName','installationAddress','installationPostcode','installationCity','brand','model','purchaseDate','installDate','amount','installerName','installerAddress','installerContact','installerPhone'].includes(key)) state.invoiceConfirmed=false;
    if(['applicantName','amount','paymentMode','payment'].includes(key)) state.paymentConfirmed=false;
    for(const k of ['codeConfirmed','invoiceConfirmed','paymentConfirmed']) document.querySelectorAll('[data-field="'+k+'"]').forEach(el=>{el.checked=state[k];});
  }
  function change(){dirty=true;saveIfEnabled();updateAside();}
  function navigate(target,anchor){page=target;history.pushState(null,'',target==='home'?(anchor?'#'+anchor:'#'):'#dossier');render();requestAnimationFrame(()=>{if(anchor)document.getElementById(anchor)?.scrollIntoView();else window.scrollTo({top:0,behavior:'instant'});});}
